24	static mi_os_mem_config_t mi_os_mem_config = {
25	  4096,     // page size
26	  0,        // large page size (usually 2MiB)
27	  4096,     // allocation granularity
28	  MI_DEFAULT_PHYSICAL_MEMORY_IN_KIB,
29	  MI_MAX_VABITS, // in `bits.h`
30	  true,     // has overcommit?  (if true we use MAP_NORESERVE on mmap systems)
31	  false,    // can we partially free allocated blocks? (on mmap systems we can free anywhere in a mapped range, but on Windows we must free the entire span)
32	  true,     // has virtual reserve? (if true we can reserve virtual address space without using commit or physical memory)
33	  false     // has transparent huge pages? (if true we purge in (aligned) large page size chunks only to not fragment such pages)
34	};
