50	// if large OS pages are supported (2 or 4MiB), then return the size, otherwise return the small page size (4KiB)
51	size_t _mi_os_large_page_size(void) {
52	  return (mi_os_mem_config.large_page_size != 0 ? mi_os_mem_config.large_page_size : _mi_os_page_size());
53	}
54	
55	// minimal purge size. Can be larger than the page size if transparent huge pages are enabled.
56	size_t _mi_os_minimal_purge_size(void) {
57	  size_t minsize = mi_option_get_size(mi_option_minimal_purge_size);
58	  if (minsize != 0) {
59	    return _mi_align_up(minsize, _mi_os_page_size());
60	  }
61	  else if (mi_os_mem_config.has_transparent_huge_pages && mi_option_get(mi_option_allow_thp) == 2) {
62	    return _mi_os_large_page_size();
63	  }
64	  else {
65	    return _mi_os_page_size();
66	  }
67	}
