81	bool _mi_os_canuse_large_page(size_t size, size_t alignment) {
82	  // if we have access, check the size and alignment requirements
83	  if (mi_os_mem_config.large_page_size == 0) return false;
84	  return ((size % mi_os_mem_config.large_page_size) == 0 && (alignment % mi_os_mem_config.large_page_size) == 0);
85	}
