87	// round to a good OS allocation size (bounded by max 12.5% waste)
88	size_t _mi_os_good_alloc_size(size_t size) {
89	  size_t align_size;
90	  if (size < 512*MI_KiB) align_size = _mi_os_page_size();
91	  else if (size < 2*MI_MiB) align_size = 64*MI_KiB;
92	  else if (size < 8*MI_MiB) align_size = 256*MI_KiB;
93	  else if (size < 32*MI_MiB) align_size = 1*MI_MiB;
94	  else align_size = 4*MI_MiB;
95	  if mi_unlikely(size >= (SIZE_MAX - align_size)) return size; // possible overflow?
96	  return _mi_align_up(size, align_size);
97	}
