104	/* -----------------------------------------------------------
105	  Util
106	-------------------------------------------------------------- */
107	bool _mi_os_decommit(mi_subproc_t* subproc, void* addr, size_t size);
108	bool _mi_os_commit(mi_subproc_t* subproc, void* addr, size_t size, bool* is_zero);
109	
110	// On systems with enough virtual address bits, we can do efficient aligned allocation by using
111	// the 2TiB to 30TiB area to allocate those. If we have at least 46 bits of virtual address
112	// space (64TiB) we use this technique. (but see issue #939)
113	#if (MI_INTPTR_SIZE >= 8) && !defined(MI_NO_ALIGNED_HINT) // && !defined(WIN32) && !defined(ANDROID)
114	
115	// Return a `try_alignment` aligned address that is probably available.
116	// If this returns NULL, the OS will determine the address but on some OS's that may not be
117	// properly aligned which can be more costly as it needs to be adjusted afterwards.
118	// In secure mode, for a size > 16GiB this always returns NULL in order to guarantee good ASLR randomization;
119	// (otherwise an initial large allocation of say 2TiB has a 50% chance to include (known) addresses
120	//  in the middle of the 2TiB - 6TiB address range (see issue #372))
121	
122	#define MI_HINT_BASE  ((uintptr_t)2 << 40)  // 2TiB start
123	#define MI_HINT_AREA  ((uintptr_t)4 << 40)  // upto (2+4) 6TiB  (since before win8 there is "only" 8TiB available to processes)
124	#define MI_HINT_MAX   ((uintptr_t)30 << 40) // wrap after 30TiB (area after 32TiB is used for huge OS pages)
125	
126	void* _mi_os_get_aligned_hint(size_t try_alignment, size_t sze)
127	{
128	  static mi_decl_cache_align _Atomic(uintptr_t) aligned_base; // = 0
129	
130	  // todo: perhaps only do alignment hints if THP is enabled?
131	  if (try_alignment <= mi_os_mem_config.alloc_granularity || try_alignment > 16*MI_GiB) return NULL;
132	  if (mi_os_mem_config.virtual_address_bits < 46) return NULL;  // < 64TiB virtual address space
133	  
134	  size_t req_size = sze + _mi_os_page_size(); // always reserve a bit more to create virtual gaps between hinted blocks.
135	  req_size += (try_alignment - 1);      // ensure we can align in the requested size
136	  req_size = _mi_align_up(req_size, _mi_os_large_page_size());
137	  #if (MI_SECURE>=1)
138	  if (req_size > 32*MI_GiB) return NULL;  // guarantee the chance of fixed valid address is at most 1/(MI_HINT_AREA / 1<<34) = 1/256
139	  #endif
140	  
141	  uintptr_t hint = mi_atomic_add_acq_rel(&aligned_base, req_size);
142	  if (hint == 0 || hint > MI_HINT_MAX) {   // wrap or initialize
143	    uintptr_t init = MI_HINT_BASE;
144	    #if (MI_SECURE>=1 || !MI_DEBUG)  // security: randomize start of aligned allocations unless in debug mode
145	    mi_theap_t* const theap = _mi_theap_default();     // don't use `mi_theap_get_default()` as that can cause allocation recursively (issue #1267)
146	    if (!mi_theap_is_initialized(theap)) return NULL;  // no hint as we lack randomness at this point
147	    const uintptr_t r = _mi_theap_random_next(theap);
148	    init = init + ((MI_MiB * ((r>>17) & 0x3FFFFF)) % MI_HINT_AREA);  // (randomly 22 bits)* 1MiB == 0 to 4TiB
149	    #endif
150	    uintptr_t expected = hint + req_size;
151	    mi_atomic_cas_strong_acq_rel(&aligned_base, &expected, init);
152	    hint = mi_atomic_add_acq_rel(&aligned_base, req_size); // this may still give 0 or > MI_HINT_MAX but that is ok, it is a hint after all
153	    if (hint==0) return NULL;
154	  }
155	  const uintptr_t hint_align = _mi_align_up(hint,try_alignment);
156	  mi_assert_internal(hint_align + sze < hint + req_size);
157	  return (void*)hint_align;
158	}
159	#else
160	void* _mi_os_get_aligned_hint(size_t try_alignment, size_t size) {
161	   MI_UNUSED(try_alignment); MI_UNUSED(size);
162	   return NULL;
163	}
164	#endif
