171	// In secure mode, return the size of a guard page, otherwise 0
172	size_t _mi_os_secure_guard_page_size(void) {
173	  #if MI_SECURE > 0
174	  return _mi_os_guard_page_size();
175	  #else
176	  return 0;
177	  #endif
178	}
