180	// In secure mode, try to decommit an area and output a warning if this fails.
181	bool _mi_os_secure_guard_page_set_at(mi_subproc_t* subproc, void* addr, mi_memid_t memid) {
182	  if (addr == NULL) return true;
183	  #if MI_SECURE > 0
184	  bool ok = false;
185	  if (!memid.is_pinned) {
186	    mi_arena_t* const arena = mi_memid_arena(memid);
187	    if (arena != NULL && arena->commit_fun != NULL) {
188	      ok = (*(arena->commit_fun))(false /* decommit */, addr, _mi_os_secure_guard_page_size(), NULL, arena->commit_fun_arg);
189	    }
190	    else {
191	      ok = _mi_os_decommit(subproc, addr, _mi_os_secure_guard_page_size());
192	    }
193	  }
194	  if (!ok) {
195	    _mi_error_message(EINVAL, "secure level %d, but failed to commit guard page (at %p of size %zu)\n", MI_SECURE, addr, _mi_os_secure_guard_page_size());
196	  }
197	  return ok;
198	  #else
199	  MI_UNUSED(subproc); MI_UNUSED(memid);
200	  return true;
201	  #endif
202	}
203	
204	// In secure mode, try to decommit an area and output a warning if this fails.
205	bool _mi_os_secure_guard_page_set_before(mi_subproc_t* subproc, void* addr, mi_memid_t memid) {
206	  return _mi_os_secure_guard_page_set_at(subproc, (uint8_t*)addr - _mi_os_secure_guard_page_size(), memid);
207	}
