209	// In secure mode, try to recommit an area
210	bool _mi_os_secure_guard_page_reset_at(mi_subproc_t* subproc, void* addr, mi_memid_t memid) {
211	  if (addr == NULL) return true;
212	  #if MI_SECURE > 0
213	  if (!memid.is_pinned) {
214	    mi_arena_t* const arena = mi_memid_arena(memid);
215	    if (arena != NULL && arena->commit_fun != NULL) {
216	      return (*(arena->commit_fun))(true, addr, _mi_os_secure_guard_page_size(), NULL, arena->commit_fun_arg);
217	    }
218	    else {
219	      return _mi_os_commit(subproc, addr, _mi_os_secure_guard_page_size(), NULL);
220	    }
221	  }
222	  #else
223	  MI_UNUSED(subproc); MI_UNUSED(memid);
224	  #endif
225	  return true;
226	}
