234	/* -----------------------------------------------------------
235	  Free memory
236	-------------------------------------------------------------- */
237	
238	static void mi_os_free_huge_os_pages(mi_subproc_t* subproc, void* p, size_t size);
239	
240	static void mi_os_prim_free(mi_subproc_t* subproc, void* addr, size_t size, size_t commit_size, bool adjust) {
241	  mi_assert_internal(subproc!=NULL);
242	  mi_assert_internal((size % _mi_os_page_size()) == 0);
243	  if (addr == NULL) return; // || _mi_os_is_huge_reserved(addr)
244	  int err = _mi_prim_free(addr, size);  // allow size==0 (issue #1041)
245	  if (err != 0) {
246	    _mi_warning_message("unable to free OS memory (error: %d (0x%x), size: 0x%zx bytes, address: %p)\n", err, err, size, addr);
247	  }
248	  if (adjust) {
249	    if (commit_size>0) { mi_subproc_stat_adjust_decrease(subproc, committed, commit_size); }
250	    mi_subproc_stat_adjust_decrease(subproc, reserved, size);
251	  }
252	  else {
253	    if (commit_size>0) { mi_subproc_stat_decrease(subproc, committed, commit_size); }
254	    mi_subproc_stat_decrease(subproc, reserved, size);
255	  }
256	}
257	
258	void _mi_os_free_ex(mi_subproc_t* subproc, void* addr, size_t size, bool still_committed, mi_memid_t memid) {
259	  if (mi_memkind_is_os(memid.memkind)) {
260	    size_t csize = memid.mem.os.size;
261	    if (csize==0) { csize = _mi_os_good_alloc_size(size); }
262	    mi_assert_internal(csize >= size);
263	    size_t commit_size = (still_committed ? csize : 0);
264	    void* base = addr;
265	    // different base? (due to alignment)
266	    if (memid.mem.os.base != base) {
267	      mi_assert(memid.mem.os.base <= addr);
268	      base = memid.mem.os.base;
269	      const size_t diff = (uint8_t*)addr - (uint8_t*)memid.mem.os.base;
270	      if (memid.mem.os.size==0) {
271	        csize += diff;
272	      }
273	      if (still_committed) {
274	        commit_size -= diff;  // the (addr-base) part was already un-committed
275	      }
276	    }
277	    // free it
278	    if (memid.memkind == MI_MEM_OS_HUGE) {
279	      mi_assert(memid.is_pinned);
280	      mi_os_free_huge_os_pages(subproc, base, csize);
281	    }
282	    else {
283	      mi_os_prim_free(subproc, base, csize, (still_committed ? commit_size : 0), false);
284	    }
285	  }
286	  else {
287	    // nothing to do
288	    mi_assert(memid.memkind < MI_MEM_OS);
289	  }
290	}
291	
292	void  _mi_os_free(mi_subproc_t* subproc, void* p, size_t size, mi_memid_t memid) {
293	  _mi_os_free_ex(subproc, p, size, true, memid);
294	}
