297	/* -----------------------------------------------------------
298	   Primitive allocation from the OS.
299	-------------------------------------------------------------- */
300	
301	// Note: the `try_alignment` is just a hint and the returned pointer is not guaranteed to be aligned.
302	// Also `hint_addr` is a hint and may be ignored.
303	static void* mi_os_prim_alloc_at(mi_subproc_t* subproc, void* hint_addr, size_t size, size_t try_alignment, bool commit, bool allow_large, bool* is_large, bool* is_zero) {
304	  mi_assert_internal(size > 0 && (size % _mi_os_page_size()) == 0);
305	  mi_assert_internal(is_zero != NULL);
306	  mi_assert_internal(is_large != NULL);
307	  if (size == 0) return NULL;
308	  if (!commit) { allow_large = false; }
309	  if (try_alignment == 0) { try_alignment = 1; } // avoid 0 to ensure there will be no divide by zero when aligning
310	
311	  // try to align along large OS page size for larger allocations
312	  const size_t large_page_size = mi_os_mem_config.large_page_size;
313	  if (large_page_size > 0 && hint_addr == NULL && size >= 8*large_page_size && _mi_is_power_of_two(try_alignment) && try_alignment < large_page_size) {
314	    try_alignment = large_page_size;
315	  }
316	
317	  *is_zero = false;
318	  void* p = NULL;
319	  int err = _mi_prim_alloc(hint_addr, size, try_alignment, commit, allow_large, is_large, is_zero, &p);
320	  if (err != 0) {
321	    _mi_warning_message("unable to allocate OS memory (error: %d (0x%x), addr: %p, size: 0x%zx bytes, align: 0x%zx, commit: %d, allow large: %d)\n", err, err, hint_addr, size, try_alignment, commit, allow_large);
322	  }
323	
324	  mi_subproc_stat_counter_increase(subproc, mmap_calls, 1);
325	  if (p != NULL) {
326	    mi_subproc_stat_increase(subproc, reserved, size);
327	    if (commit) {
328	      mi_subproc_stat_increase(subproc, committed, size);
329	      // seems needed for asan (or `mimalloc-test-api` fails)
330	      #ifdef MI_TRACK_ASAN
331	      if (*is_zero) { mi_track_mem_defined(p,size); }
332	               else { mi_track_mem_undefined(p,size); }
333	      #endif
334	    }
335	  }
336	  return p;
337	}
338	
339	static void* mi_os_prim_alloc(mi_subproc_t* subproc, size_t size, size_t try_alignment, bool commit, bool allow_large, bool* is_large, bool* is_zero) {
340	  return mi_os_prim_alloc_at(subproc, NULL /* hint addr */, size, try_alignment, commit, allow_large, is_large, is_zero);
341	}
342	
343	
344	// Primitive aligned allocation from the OS.
345	// This function guarantees the allocated memory is aligned.
346	static void* mi_os_prim_alloc_aligned(mi_subproc_t* subproc, size_t size, size_t alignment, bool commit, bool allow_large, mi_memid_t* memid) {
347	  mi_assert_internal(memid!=NULL);
348	  mi_assert_internal(alignment >= _mi_os_page_size() && ((alignment & (alignment - 1)) == 0));
349	  mi_assert_internal(size > 0 && (size % _mi_os_page_size()) == 0);
350	  *memid = _mi_memid_none();
351	  if (!commit) allow_large = false;
352	  if (!(alignment >= _mi_os_page_size() && ((alignment & (alignment - 1)) == 0))) return NULL;
353	  size = _mi_align_up(size, _mi_os_page_size());
354	
355	  #if MI_INTPTR_SIZE >= 8
356	  const bool try_direct_alloc = true;
357	  #else
358	  // try a direct allocation if the alignment is below the default, or less than or equal to 1/4 fraction of the size.
359	  const bool try_direct_alloc = (alignment <= mi_os_mem_config.alloc_granularity || alignment <= size/4);
360	  #endif
361	
362	  bool os_is_large = false;
363	  bool os_is_zero = false;
364	  void*  os_base = NULL;
365	  size_t os_size = size;
366	  void* p = NULL;
367	  if (try_direct_alloc) {
368	    p = mi_os_prim_alloc(subproc, size, alignment, commit, allow_large, &os_is_large, &os_is_zero);
369	  }
370	
371	  // aligned already?
372	  if (p != NULL && _mi_is_aligned(p,alignment)) {
373	    os_base = p;
374	  }
375	  else {
376	    // if not aligned, free it, overallocate, and unmap around it
377	    #if !MI_TRACK_ASAN
378	    if (try_direct_alloc) {
379	      _mi_warning_message("unable to allocate aligned OS memory directly, fall back to over-allocation (size: 0x%zx bytes, address: %p, alignment: 0x%zx, commit: %d)\n", size, p, alignment, commit);
380	    }
381	    #endif
382	    if (p != NULL) { mi_os_prim_free(subproc, p, size, (commit ? size : 0), true /* adjust so we "forget" the previous reservation */); }
383	    if (size >= (SIZE_MAX - alignment)) return NULL; // overflow
384	    const size_t over_size = size + alignment;
385	
386	    if (!mi_os_mem_config.has_partial_free) {  // win32 virtualAlloc cannot free parts of an allocated block
387	      // over-allocate uncommitted (virtual) memory
388	      p = mi_os_prim_alloc(subproc, over_size, 1 /*alignment*/, false /* commit? */, false /* allow_large */, &os_is_large, &os_is_zero);
389	      if (p == NULL) return NULL;
390	
391	      // set p to the aligned part in the full region
392	      // note: Windows VirtualFree needs the actual base pointer
393	      // this is handled though by having the `base` field in the memid
394	      os_base = p; // remember the base
395	      os_size = over_size; // todo: use size instead as now we over-decrement commit stats on free?
396	      p = _mi_align_up_ptr(p, alignment);
397	
398	      // explicitly commit only the aligned part
399	      if (commit) {
400	        if (!_mi_os_commit(subproc, p, size, NULL)) {
401	          mi_os_prim_free(subproc, os_base, over_size, 0, true);
402	          return NULL;
403	        }
404	      }
405	    }
406	    else  { // mmap can free inside an allocation
407	      // overallocate...
408	      // note: we keep `allow_large` but this only works if we can partially free any large OS pages later on. This seems to be the case though.
409	      p = mi_os_prim_alloc(subproc, over_size, 1, commit, allow_large /* or false? */, &os_is_large, &os_is_zero);
410	      if (p == NULL) return NULL;
411	
412	      // and selectively unmap parts around the over-allocated area.
413	      void* const aligned_p = _mi_align_up_ptr(p, alignment);
414	      const size_t pre_size = (uint8_t*)aligned_p - (uint8_t*)p;
415	      const size_t mid_size = _mi_align_up(size, _mi_os_page_size());
416	      const size_t post_size = over_size - pre_size - mid_size;
417	      mi_assert_internal(pre_size < over_size&& post_size < over_size&& mid_size >= size);
418	      if (pre_size > 0)  { mi_os_prim_free(subproc, p, pre_size, (commit ? pre_size : 0), true /* adjust */); }
419	      if (post_size > 0) { mi_os_prim_free(subproc, (uint8_t*)aligned_p + mid_size, post_size, (commit ? post_size : 0), true /* adjust */); }
420	      // we can return the aligned pointer on `mmap` systems
421	      p = aligned_p;
422	      os_base = aligned_p; // since we freed the pre part, `*base == p`.
423	      os_size = mid_size;
424	    }
425	  }
426	
427	  mi_assert_internal(p != NULL && os_base != NULL && _mi_is_aligned(p,alignment));
428	  mi_assert_internal(os_base <= p && size <= os_size);
429	  *memid = _mi_memid_create_os(os_base,os_size,commit,os_is_zero,os_is_large);
430	  return p;
431	}
