434	/* -----------------------------------------------------------
435	  OS API: alloc and alloc_aligned
436	----------------------------------------------------------- */
437	
438	void* _mi_os_alloc(mi_subproc_t* subproc, size_t size, mi_memid_t* memid) {
439	  *memid = _mi_memid_none();
440	  if (size == 0) return NULL;
441	  size = _mi_os_good_alloc_size(size);
442	  bool os_is_large = false;
443	  bool os_is_zero  = false;
444	  void* p = mi_os_prim_alloc(subproc, size, 0, true, false, &os_is_large, &os_is_zero);
445	  if (p == NULL) return NULL;
446	
447	  *memid = _mi_memid_create_os(p, size, true, os_is_zero, os_is_large);
448	  mi_assert_internal(memid->mem.os.size >= size);
449	  mi_assert_internal(memid->initially_committed);
450	  return p;
451	}
452	
453	void* _mi_os_alloc_aligned(mi_subproc_t* subproc, size_t size, size_t alignment, bool commit, bool allow_large, mi_memid_t* memid)
454	{
455	  MI_UNUSED(&_mi_os_get_aligned_hint); // suppress unused warnings
456	  *memid = _mi_memid_none();
457	  if (size == 0) return NULL;
458	  size = _mi_os_good_alloc_size(size);
459	  alignment = _mi_align_up(alignment, _mi_os_page_size());
460	
461	  void* p = mi_os_prim_alloc_aligned(subproc, size, alignment, commit, allow_large, memid );
462	  if (p == NULL) return NULL;
463	
464	  mi_assert_internal(memid->mem.os.size >= size);
465	  mi_assert_internal(_mi_is_aligned(p,alignment));
466	  if (commit) { mi_assert_internal(memid->initially_committed); }
467	  return p;
468	}
