471	mi_decl_nodiscard static void* mi_os_ensure_zero(mi_subproc_t* subproc, void* p, size_t size, mi_memid_t* memid) {
472	  if (p==NULL || size==0) return p;
473	  // ensure committed
474	  if (!memid->initially_committed) {
475	    bool is_zero = false;
476	    if (!_mi_os_commit(subproc, p, size, &is_zero)) {
477	      _mi_os_free(subproc, p, size, *memid);
478	      return NULL;
479	    }
480	    memid->initially_committed = true;
481	  }
482	  // ensure zero'd
483	  if (memid->initially_zero) return p;
484	  _mi_memzero_aligned(p,size);
485	  memid->initially_zero = true;
486	  return p;
487	}
