494	/* -----------------------------------------------------------
495	  OS aligned allocation with an offset. This is used
496	  for large alignments > MI_BLOCK_ALIGNMENT_MAX. We use a large mimalloc
497	  page where the object can be aligned at an offset from the start of the segment.
498	  As we may need to overallocate, we need to free such pointers using `mi_free_aligned`
499	  to use the actual start of the memory region.
500	----------------------------------------------------------- */
501	
502	void* _mi_os_alloc_aligned_at_offset(mi_subproc_t* subproc, size_t size, size_t alignment, size_t offset, bool commit, bool allow_large, mi_memid_t* memid) {
503	  mi_assert(offset <= size);
504	  mi_assert((alignment % _mi_os_page_size()) == 0);
505	  *memid = _mi_memid_none();
506	  if (offset > size) return NULL;
507	  if (offset == 0) {
508	    // regular aligned allocation
509	    return _mi_os_alloc_aligned(subproc, size, alignment, commit, allow_large, memid);
510	  }
511	  else {
512	    // overallocate to align at an offset
513	    const size_t extra = _mi_align_up(offset, alignment) - offset;
514	    if (size >= SIZE_MAX - extra) return NULL;  // too large
515	    const size_t oversize = size + extra;
516	    void* const start = _mi_os_alloc_aligned(subproc, oversize, alignment, commit, allow_large, memid);
517	    if (start == NULL) return NULL;
518	
519	    void* const p = (uint8_t*)start + extra;
520	    mi_assert(_mi_is_aligned((uint8_t*)p + offset, alignment));
521	    // decommit the overallocation at the start
522	    // note: this double counts the decommit when freeing `memid`. Should we keep commit size in the memid as well?
523	    if (commit && extra >= _mi_os_page_size()) {
524	      _mi_os_decommit(subproc, start, extra);
525	    }
526	    return p;
527	  }
528	}
