533	
534	// OS page align within a given area, either conservative (pages inside the area only),
535	// or not (straddling pages outside the area is possible)
536	static void* mi_os_page_align_areax(bool conservative, void* addr, size_t size, size_t* newsize) {
537	  mi_assert(addr != NULL && size > 0);
538	  if (newsize != NULL) *newsize = 0;
539	  if (size == 0 || addr == NULL) return NULL;
540	
541	  // page align conservatively within the range, or liberally straddling pages outside the range
542	  void* start = (conservative ? _mi_align_up_ptr(addr, _mi_os_page_size())
543	                              : _mi_align_down_ptr(addr, _mi_os_page_size()));
544	  void* end   = (conservative ? _mi_align_down_ptr((uint8_t*)addr + size, _mi_os_page_size())
545	                              : _mi_align_up_ptr((uint8_t*)addr + size, _mi_os_page_size()));
546	  ptrdiff_t diff = (uint8_t*)end - (uint8_t*)start;
547	  if (diff <= 0) return NULL;
548	
549	  mi_assert_internal((conservative && (size_t)diff <= size) || (!conservative && (size_t)diff >= size));
550	  if (newsize != NULL) *newsize = (size_t)diff;
551	  return start;
552	}
553	
554	static void* mi_os_page_align_area_conservative(void* addr, size_t size, size_t* newsize) {
555	  return mi_os_page_align_areax(true, addr, size, newsize);
556	}
557	
558	bool _mi_os_commit_ex(mi_subproc_t* subproc, void* addr, size_t size, bool* is_zero, size_t stat_already_committed) {
559	  mi_assert_internal(size >= stat_already_committed);
560	  if (is_zero != NULL) { *is_zero = false; }
561	  mi_subproc_stat_counter_increase(subproc, commit_calls, 1);
562	
563	  // page align range
564	  size_t csize;
565	  void* start = mi_os_page_align_areax(false /* conservative? */, addr, size, &csize);
566	  if (csize == 0) return true;
567	
568	  // commit
569	  bool os_is_zero = false;
570	  int err = _mi_prim_commit(start, csize, &os_is_zero);
571	  if (err != 0) {
572	    _mi_warning_message("cannot commit OS memory (error: %d (0x%x), address: %p, size: 0x%zx bytes)\n", err, err, start, csize);
573	    return false;
574	  }
575	  if (os_is_zero && is_zero != NULL) {
576	    *is_zero = true;
577	    mi_assert_expensive(mi_mem_is_zero(start, csize));
578	  }
579	  // note: the following seems required for asan (otherwise `mimalloc-test-stress` fails)
580	  #ifdef MI_TRACK_ASAN
581	  if (os_is_zero) { mi_track_mem_defined(start,csize); }
582	             else { mi_track_mem_undefined(start,csize); }
583	  #endif
584	  mi_subproc_stat_increase(subproc, committed, size - stat_already_committed);  // for precise commit vs. decommit
585	  return true;
586	}
587	
588	bool _mi_os_commit(mi_subproc_t* subproc, void* addr, size_t size, bool* is_zero) {
589	  return _mi_os_commit_ex(subproc, addr, size, is_zero, 0);
590	}
