592	static bool mi_os_decommit_ex(mi_subproc_t* subproc, void* addr, size_t size, bool* needs_recommit, size_t stat_size) {
593	  mi_assert_internal(needs_recommit!=NULL);
594	
595	  // page align
596	  size_t csize;
597	  void* start = mi_os_page_align_area_conservative(addr, size, &csize);
598	  if (csize == 0) return true;
599	
600	  // decommit
601	  *needs_recommit = true;
602	  int err = _mi_prim_decommit(start,csize,needs_recommit);
603	  if (err != 0) {
604	    _mi_warning_message("cannot decommit OS memory (error: %d (0x%x), address: %p, size: 0x%zx bytes)\n", err, err, start, csize);
605	  }
606	  else if (*needs_recommit) {
607	    mi_subproc_stat_decrease(subproc, committed, stat_size);
608	  }
609	  mi_assert_internal(err == 0);
610	  return (err == 0);
611	}
612	
613	bool _mi_os_decommit(mi_subproc_t* subproc, void* addr, size_t size) {
614	  bool needs_recommit;
615	  return mi_os_decommit_ex(subproc, addr, size, &needs_recommit, size);
616	}
