619	// Signal to the OS that the address range is no longer in use
620	// but may be used later again. This will release physical memory
621	// pages and reduce swapping while keeping the memory committed.
622	// We page align to a conservative area inside the range to reset.
623	bool _mi_os_reset(mi_subproc_t* subproc, void* addr, size_t size) {
624	  // page align conservatively within the range
625	  size_t csize;
626	  void* start = mi_os_page_align_area_conservative(addr, size, &csize);
627	  if (csize == 0) return true;  // || _mi_os_is_huge_reserved(addr)
628	  mi_subproc_stat_counter_increase(subproc, reset, csize);
629	  mi_subproc_stat_counter_increase(subproc, reset_calls, 1);
630	
631	  #if (MI_DEBUG>1) && !MI_SECURE && !MI_TRACK_ENABLED // && !MI_TSAN
632	  memset(start, 0, csize); // pretend it is eagerly reset
633	  #endif
634	
635	  int err = _mi_prim_reset(start, csize);
636	  if (err != 0) {
637	    _mi_warning_message("cannot reset OS memory (error: %d (0x%x), address: %p, size: 0x%zx bytes)\n", err, err, start, csize);
638	  }
639	  return (err == 0);
640	}
