643	void _mi_os_reuse( mi_subproc_t* subproc, void* addr, size_t size ) { 
644	  MI_UNUSED(subproc);
645	  // page align conservatively within the range
646	  size_t csize = 0;
647	  void* const start = mi_os_page_align_area_conservative(addr, size, &csize);
648	  if (csize == 0) return;
649	  const int err = _mi_prim_reuse(start, csize);
650	  if (err != 0) {
651	    _mi_warning_message("cannot reuse OS memory (error: %d (0x%x), address: %p, size: 0x%zx bytes)\n", err, err, start, csize);
652	  }
653	}
