655	// either resets or decommits memory, returns true if the memory needs
656	// to be recommitted if it is to be re-used later on.
657	bool _mi_os_purge_ex(mi_subproc_t* subproc, void* p, size_t size, bool allow_reset, size_t stat_size, mi_commit_fun_t* commit_fun, void* commit_fun_arg)
658	{
659	  if (mi_option_get(mi_option_purge_delay) < 0) return false;  // is purging allowed?
660	  mi_subproc_stat_counter_increase(subproc, purge_calls, 1);
661	  mi_subproc_stat_counter_increase(subproc, purged, size);
662	
663	  if (commit_fun != NULL) {
664	    bool decommitted = (*commit_fun)(false, p, size, NULL, commit_fun_arg);
665	    return decommitted; // needs_recommit?
666	  }
667	  else if (mi_option_is_enabled(mi_option_purge_decommits) &&   // should decommit?
668	           !_mi_preloading())                                   // don't decommit during preloading (unsafe)
669	  {
670	    bool needs_recommit = true;
671	    mi_os_decommit_ex(subproc, p, size, &needs_recommit, stat_size);
672	    return needs_recommit;
673	  }
674	  else {
675	    if (allow_reset) {  // this can sometimes be not allowed if the range is not fully committed (on Windows, we cannot reset uncommitted memory)
676	      _mi_os_reset(subproc, p, size);
677	    }
678	    return false;  // needs no recommit
679	  }
680	}
