689	// Protect a region in memory to be not accessible.
690	static  bool mi_os_protectx(void* addr, size_t size, bool protect) {
691	  // page align conservatively within the range
692	  size_t csize = 0;
693	  void* start = mi_os_page_align_area_conservative(addr, size, &csize);
694	  if (csize == 0) return false;
695	  /*
696	  if (_mi_os_is_huge_reserved(addr)) {
697		  _mi_warning_message("cannot mprotect memory allocated in huge OS pages\n");
698	  }
699	  */
700	  int err = _mi_prim_protect(start,csize,protect);
701	  if (err != 0) {
702	    _mi_warning_message("cannot %s OS memory (error: %d (0x%x), address: %p, size: 0x%zx bytes)\n", (protect ? "protect" : "unprotect"), err, err, start, csize);
703	  }
704	  return (err == 0);
705	}
