717	/* ----------------------------------------------------------------------------
718	Support for allocating huge OS pages (1Gib) that are reserved up-front
719	and possibly associated with a specific NUMA node. (use `numa_node>=0`)
720	-----------------------------------------------------------------------------*/
721	#define MI_HUGE_OS_PAGE_SIZE  (MI_GiB)
722	
723	
724	#if (MI_INTPTR_SIZE >= 8)
725	// To ensure proper alignment, use our own area for huge OS pages
726	static mi_decl_cache_align _Atomic(uintptr_t)  mi_huge_start; // = 0
727	
728	// Claim an aligned address range for huge pages
729	static uint8_t* mi_os_claim_huge_pages(size_t pages, size_t* total_size) {
730	  if (total_size != NULL) *total_size = 0;
731	  size_t size = 0;
732	  if (mi_mul_overflow(pages,MI_HUGE_OS_PAGE_SIZE,&size)) {
733	    _mi_warning_message("too many huge pages requested: %zu\n", pages);
734	    return NULL;
735	  }
736	
737	  uintptr_t start = 0;
738	  uintptr_t end = 0;
739	  uintptr_t huge_start = mi_atomic_load_relaxed(&mi_huge_start);
740	  do {
741	    start = huge_start;
742	    if (start == 0) {
743	      // Initialize the start address after the 32TiB area
744	      start = ((uintptr_t)32 << 40);    // 32TiB virtual start address (after addresses returned by _mi_os_get_aligned_hint)
745	      #if (MI_SECURE>0 || MI_DEBUG==0)  // security: randomize start of huge pages unless in debug mode
746	      mi_theap_t* const theap = _mi_theap_default();     // don't use `mi_theap_get_default()` as that can cause allocation recursively (issue #1267)
747	      if (mi_theap_is_initialized(theap)) {              // todo: or no hint at all if we lack randomness?
748	        const uintptr_t r = _mi_theap_random_next(theap);
749	        start = start + ((uintptr_t)MI_HUGE_OS_PAGE_SIZE * ((r>>17) & 0x0FFF));  // (randomly 12bits)*1GiB == between 0 to 4TiB
750	      }
751	      else {
752	        _mi_warning_message("failed to randomize the start address of huge pages allocation (%zu bytes at %p)", size, (void*)start);
753	      }
754	      #endif
755	    }
756	    end = start + size;
757	  } while (!mi_atomic_cas_weak_acq_rel(&mi_huge_start, &huge_start, end));
758	
759	  if (total_size != NULL) *total_size = size;
760	  return (uint8_t*)start;
761	}
762	#else
763	static uint8_t* mi_os_claim_huge_pages(size_t pages, size_t* total_size) {
764	  MI_UNUSED(pages);
765	  if (total_size != NULL) *total_size = 0;
766	  return NULL;
767	}
768	#endif
769	
770	// Allocate MI_ARENA_SLICE_ALIGN aligned huge pages
771	void* _mi_os_alloc_huge_os_pages(mi_subproc_t* subproc, size_t pages, int numa_node, mi_msecs_t max_msecs, size_t* pages_reserved, size_t* psize, mi_memid_t* memid) {
772	  *memid = _mi_memid_none();
773	  if (psize != NULL) *psize = 0;
774	  if (pages_reserved != NULL) *pages_reserved = 0;
775	  size_t size = 0;
776	  uint8_t* const start = mi_os_claim_huge_pages(pages, &size);
777	  if (start == NULL) return NULL; // or 32-bit systems
778	
779	  // Allocate one page at the time but try to place them contiguously
780	  // We allocate one page at the time to be able to abort if it takes too long
781	  // or to at least allocate as many as available on the system.
782	  mi_msecs_t start_t = _mi_clock_start();
783	  size_t page = 0;
784	  bool all_zero = true;
785	  while (page < pages) {
786	    // allocate a page
787	    bool is_zero = false;
788	    void* addr = start + (page * MI_HUGE_OS_PAGE_SIZE);
789	    void* p = NULL;
790	    int err = _mi_prim_alloc_huge_os_pages(addr, MI_HUGE_OS_PAGE_SIZE, numa_node, &is_zero, &p);
791	    if (!is_zero) { all_zero = false;  }
792	    if (err != 0) {
793	      _mi_warning_message("unable to allocate huge OS page (error: %d (0x%x), address: %p, size: %zx bytes)\n", err, err, addr, MI_HUGE_OS_PAGE_SIZE);
794	      break;
795	    }
796	
797	    // Did we succeed at a contiguous address?
798	    if (p != addr) {
799	      // no success, issue a warning and break
800	      if (p != NULL) {
801	        _mi_warning_message("could not allocate contiguous huge OS page %zu at %p\n", page, addr);
802	        mi_os_prim_free(subproc, p, MI_HUGE_OS_PAGE_SIZE, MI_HUGE_OS_PAGE_SIZE, true /* adjust */);
803	      }
804	      break;
805	    }
806	
807	    // success, record it
808	    page++;  // increase before timeout check (see issue #711)
809	    mi_subproc_stat_increase(subproc, committed, MI_HUGE_OS_PAGE_SIZE);
810	    mi_subproc_stat_increase(subproc, reserved, MI_HUGE_OS_PAGE_SIZE);
811	
812	    // check for timeout
813	    if (max_msecs > 0) {
814	      mi_msecs_t elapsed = _mi_clock_end(start_t);
815	      if (page >= 1) {
816	        mi_msecs_t estimate = ((elapsed / (page==0 ? 1 : page)) * pages);
817	        if (estimate > 2*max_msecs) { // seems like we are going to timeout, break
818	          elapsed = max_msecs + 1;
819	        }
820	      }
821	      if (elapsed > max_msecs) {
822	        _mi_warning_message("huge OS page allocation timed out (after allocating %zu page(s))\n", page);
823	        break;
824	      }
825	    }
826	  }
827	  const size_t allocated = page * MI_HUGE_OS_PAGE_SIZE;
828	  mi_assert_internal(allocated <= size);
829	  if (pages_reserved != NULL) { *pages_reserved = page; }
830	  if (psize != NULL) { *psize = allocated; }
831	  if (page != 0) {
832	    mi_assert(start != NULL);
833	    *memid = _mi_memid_create_os(start, allocated, true /* is committed */, all_zero, true /* is_large */);
834	    memid->memkind = MI_MEM_OS_HUGE;
835	    mi_assert(memid->is_pinned);
836	    #ifdef MI_TRACK_ASAN
837	    if (all_zero) { mi_track_mem_defined(start,allocated); }
838	    #endif
839	  }
840	  return (page == 0 ? NULL : start);
841	}
842	
843	// free every huge page in a range individually (as we allocated per page)
844	// note: needed with VirtualAlloc but could potentially be done in one go on mmap'd systems.
845	static void mi_os_free_huge_os_pages(mi_subproc_t* subproc, void* p, size_t size) {
846	  if (p==NULL || size==0) return;
847	  uint8_t* base = (uint8_t*)p;
848	  while (size >= MI_HUGE_OS_PAGE_SIZE) {
849	    mi_os_prim_free(subproc, base, MI_HUGE_OS_PAGE_SIZE, MI_HUGE_OS_PAGE_SIZE, false /* adjust? */);
850	    size -= MI_HUGE_OS_PAGE_SIZE;
851	    base += MI_HUGE_OS_PAGE_SIZE;
852	  }
853	}
