859	
860	static _Atomic(size_t) mi_numa_node_count; // = 0   // cache the node count
861	
862	int _mi_os_numa_node_count(void) {
863	  size_t count = mi_atomic_load_acquire(&mi_numa_node_count);
864	  if mi_unlikely(count == 0) {
865	    long ncount = mi_option_get(mi_option_use_numa_nodes); // given explicitly?
866	    if (ncount > 0 && ncount < INT_MAX) {
867	      count = (size_t)ncount;
868	    }
869	    else {
870	      const size_t n = _mi_prim_numa_node_count(); // or detect dynamically
871	      if (n == 0 || n > INT_MAX) { count = 1; }
872	                            else { count = n; }
873	    }
874	    mi_atomic_store_release(&mi_numa_node_count, count); // save it
875	    if (count>1) { _mi_verbose_message("using %zd numa regions\n", count); }
876	  }
877	  mi_assert_internal(count > 0 && count <= INT_MAX);
878	  return (int)count;
879	}
880	
881	static int mi_os_numa_node_get(void) {
882	  int numa_count = _mi_os_numa_node_count();
883	  if (numa_count<=1) return 0; // optimize on single numa node systems: always node 0
884	  // never more than the node count and >= 0
885	  const size_t n = _mi_prim_numa_node();
886	  int numa_node = (n < INT_MAX ? (int)n : 0);
887	  if (numa_node >= numa_count) { numa_node = numa_node % numa_count; }
888	  return numa_node;
889	}
890	
891	int _mi_os_numa_node(void) {
892	  if mi_likely(mi_atomic_load_relaxed(&mi_numa_node_count) == 1) {
893	    return 0;
894	  }
895	  else {
896	    return mi_os_numa_node_get();
897	  }
898	}
