413	// The program should only install a single output handler from a single thread
414	// since otherwise the argument and output function may not match.
415	static _Atomic(void*) mi_out_default; // = // is `mi_output_fun*` (but some platforms don't support atomic function pointers)
416	static _Atomic(void*) mi_out_arg; // = NULL
417	
418	static mi_output_fun* mi_out_get_default(void** parg) {
419	  mi_output_fun* const out = (mi_output_fun*)mi_atomic_load_ptr_acquire(void,&mi_out_default);
420	  if (parg != NULL) { *parg = mi_atomic_load_ptr_acquire(void,&mi_out_arg); }
421	  return (out == NULL ? &mi_out_buf : out);
422	}
