521	int _mi_prim_commit(void* start, size_t size, bool* is_zero) {
522	  // commit: ensure we can access the area
523	  // note: we may think that *is_zero can be true since the memory
524	  // was either from mmap PROT_NONE, or from decommit MADV_DONTNEED, but
525	  // we sometimes call commit on a range with still partially committed
526	  // memory and `mprotect` does not zero the range.
527	  *is_zero = false;
528	  int err = mprotect(start, size, (PROT_READ | PROT_WRITE));
529	  if (err != 0) {
530	    err = errno;
531	    unix_mprotect_hint(err);
532	  }
533	  return err;
534	}
